import assert from 'node:assert/strict';
import { makeSandbox, makeNode, allByClass } from './poc_dom.mjs';
const [app, raw] = process.argv.slice(2);
const {sandbox,store} = makeSandbox(app, () => ({}));
const shown=JSON.parse(raw);
const feed=makeNode('div'), ta=makeNode('textarea'); ta.value='свои слова';
const pick={addr:'synthetic',on:true,ask:{kind:'agent',task:'XR-1',text:'вопрос',proposal:shown}};
sandbox.proposalPickWire(feed,ta,pick,shown);
assert.equal(allByClass(feed,'draft-proposal').length,3);
const comment = sandbox.proposalComment(pick.proposalDraft);
assert.equal(comment.mode, 'comment');
assert.equal(comment.snapshots.length, 2);
assert.equal(comment.decisions.length, 0);
const first=allByClass(feed,'draft-proposal')[0];
const select=first.querySelector('select'), reason=first.querySelector('input');
select.value='reject'; select.handlers.change(); reason.value='не подходит'; reason.handlers.input();
assert.equal(ta.value,'свои слова');
const saved=JSON.parse(store.get('devkit.askdraft.synthetic'));
assert.equal(saved.proposalDraft.decisions[0].reason,'не подходит');
shown.sources[0].basis='новый';
const answer=sandbox.proposalAnswer(saved.proposalDraft);
assert.equal(answer.snapshots[0].digest,'old');
assert.equal(answer.decisions.length,1);
assert.equal(answer.decisions[0].action,'reject');
console.log('proposal UI selection and persistence: ok');
